import requests

def main(task_id: str) -> dict:
    if not task_id:
        return {"result": ""}
    progress = "10%"
    info = "搜索公司基本信息中"

    url = f"http://bm.vsource.club/api/deep-research/tasks/{task_id}/progress"

    # 准备请求数据
    data = {"progress": progress}
    if info:
        data["info"] = info

    try:
        # 发送请求
        response = requests.post(
            url, 
            json=data,
            headers={"Content-Type": "application/json"}
        )

        # 检查响应状态
        if response.status_code == 200:
            result = response.json()
            return {"result": "上报成功"}
        else:
            return {"result": "上报失败" + str(response.content)}

    except Exception as e:
        return {"result": "上报失败" + str(e)}

